"collection": "dishes",
"q": "*",
"filter_by": "$restaurants(id:=restaurant_a || rating: 5) && $dish_tags($tags(id: [tag_a, tag_c, tag_e, tag_f]))",
"include_fields": "$dish_tags($tags(name, rating, strategy: merge), strategy:nest_array)",
